I need to analyze this step by step:

1. Get mental health burden rates per gender x age group from survey data
2. Classify age groups as high/low burden within each gender
3. Get total claim amounts per patient from synthea, stratified by gender x age group
4. Return aggregated stats needed for Welch's t-test

Let me build the queries:

**Query 1**: Get mental health burden rates per gender x age group from survey (QuestionID for age=1, gender=2, mental health=need to find 'Yes' answers)

**Query 2**: Get per-patient total claims with gender and age group from synthea

[
  {
    "db": "mental_health_survey",
    "sql": "SELECT gender_ans.AnswerText AS gender, CASE WHEN CAST(age_ans.AnswerText AS INTEGER) BETWEEN 18 AND 34 THEN '18-34' WHEN CAST(age_ans.AnswerText AS INTEGER) BETWEEN 35 AND 49 THEN '35-49' WHEN CAST(age_ans.AnswerText AS INTEGER) BETWEEN 50 AND 65 THEN '50-65' END AS age_group, COUNT(*) AS total_respondents, SUM(CASE WHEN mh_ans.AnswerText = 'Yes' THEN 1 ELSE 0 END) AS yes_count, CAST(SUM(CASE WHEN mh_ans.AnswerText = 'Yes' THEN 1 ELSE 0 END) AS REAL) / COUNT(*) AS burden_rate FROM Answer age_ans JOIN Answer gender_ans ON age_ans.UserID = gender_ans.UserID JOIN Answer mh_ans ON age_ans.UserID = mh_ans.UserID WHERE age_ans.QuestionID = 1 AND gender_ans.QuestionID = 2 AND mh_ans.QuestionID IN (SELECT questionid FROM Question WHERE LOWER(questiontext) LIKE '%mental health%' AND LOWER(questiontext) LIKE '%yes%') AND gender_ans.AnswerText IN ('Male', 'Female') AND CAST(age_ans.AnswerText AS INTEGER) BETWEEN 18 AND 65 GROUP BY gender_ans.AnswerText, age_group HAVING age_group IS NOT NULL"
  },
  {
    "db": "mental_health_survey",
    "sql": "SELECT questionid, questiontext FROM Question WHERE LOWER(questiontext) LIKE '%mental%' OR LOWER(questiontext) LIKE '%treatment%' OR LOWER(questiontext) LIKE '%disorder%' OR LOWER(questiontext) LIKE '%seek%' OR LOWER(questiontext) LIKE '%interfere%' OR LOWER(questiontext) LIKE '%condition%'"
  },
  {
    "db": "mental_health_survey",
    "sql": "SELECT q.questionid, q.questiontext, a.AnswerText, COUNT(*) as cnt FROM Question q JOIN Answer a ON q.questionid = a.QuestionID WHERE a.AnswerText IN ('Yes','No','Maybe') GROUP BY q.questionid, q.questiontext, a.AnswerText ORDER BY q.questionid, cnt DESC"
  },
  {
    "db": "mental_health_survey",
    "sql": "WITH age_ans AS (SELECT UserID, CAST(AnswerText AS INTEGER) AS age FROM Answer WHERE QuestionID = 1), gender_ans AS (SELECT UserID, AnswerText AS gender FROM Answer WHERE QuestionID = 2 AND AnswerText IN ('Male','Female')), mh_qs AS (SELECT DISTINCT QuestionID FROM Answer WHERE AnswerText = 'Yes' AND QuestionID NOT IN (1,2,3)), yes_users AS (SELECT DISTINCT a.UserID FROM Answer a WHERE a.AnswerText = 'Yes' AND a.QuestionID IN (SELECT QuestionID FROM mh_qs)), base AS (SELECT g.UserID, g.gender, CASE WHEN aa.age BETWEEN 18 AND 34 THEN '18-34' WHEN aa.age BETWEEN 35 AND 49 THEN '35-49' WHEN aa.age BETWEEN 50 AND 65 THEN '50-65' END AS age_group FROM gender_ans g JOIN age_ans aa ON g.UserID = aa.UserID WHERE aa.age BETWEEN 18 AND 65) SELECT b.gender, b.age_group, COUNT(DISTINCT b.UserID) AS total, SUM(CASE WHEN y.UserID IS NOT NULL THEN 1 ELSE 0 END) AS yes_count, CAST(SUM(CASE WHEN y.UserID IS NOT NULL THEN 1 ELSE 0 END) AS REAL)/COUNT(DISTINCT b.UserID) AS burden_rate FROM base b LEFT JOIN yes_users y ON b.UserID = y.UserID WHERE b.age_group IS NOT NULL GROUP BY b.gender, b.age_group ORDER BY b.gender, b.age_group"
  },
  {
    "db": "mental_health_survey",
    "sql": "SELECT QuestionID, questiontext FROM Question"
  },
  {
    "db": "mental_health_survey",
    "sql": "WITH age_q AS (SELECT 1 AS qid), gender_q AS (SELECT 2 AS qid), mh_burden_q AS (SELECT questionid FROM Question WHERE LOWER(questiontext) LIKE '%mental health%' AND (LOWER(questiontext) LIKE '%interfer%' OR LOWER(questiontext) LIKE '%treatment%' OR LOWER(questiontext) LIKE '%sought%' OR LOWER(questiontext) LIKE '%sought%' OR LOWER(questiontext) LIKE '%diagnos%')), ages AS (SELECT UserID, CAST(AnswerText AS INTEGER) AS age FROM Answer WHERE QuestionID = 1 AND CAST(AnswerText AS INTEGER) BETWEEN 18 AND 65), genders AS (SELECT UserID, AnswerText AS gender FROM Answer WHERE QuestionID = 2 AND AnswerText IN ('Male','Female')), mh_yes AS (SELECT DISTINCT UserID FROM Answer WHERE QuestionID IN (SELECT questionid FROM mh_burden_q) AND AnswerText = 'Yes'), combined AS (SELECT a.UserID, g.gender, CASE WHEN a.age BETWEEN 18 AND 34 THEN '18-34' WHEN a.age BETWEEN 35 AND 49 THEN '35-49' WHEN a.age BETWEEN 50 AND 65 THEN '50-65' END AS age_group FROM ages a JOIN genders g ON a.UserID = g.UserID) SELECT c.gender, c.age_group, COUNT(DISTINCT c.UserID) AS total_respondents, SUM(CASE WHEN m.UserID IS NOT NULL THEN 1 ELSE 0 END) AS yes_count, CAST(SUM(CASE WHEN m.UserID IS NOT NULL THEN 1 ELSE 0 END) AS REAL) / COUNT(DISTINCT c.UserID) AS burden_rate FROM combined c LEFT JOIN mh_yes m ON c.UserID = m.UserID WHERE c.age_group IS NOT NULL GROUP BY c.gender, c.age_group ORDER BY c.gender, c.age_group"
  },
  {
    "db": "mental_health_survey",
    "sql": "SELECT a.QuestionID, q.questiontext, COUNT(DISTINCT a.UserID) as respondents FROM Answer a JOIN Question q ON a.QuestionID = q.questionid WHERE a.AnswerText = 'Yes' GROUP BY a.QuestionID, q.questiontext ORDER BY respondents DESC LIMIT 20"
  },
  {
    "db": "mental_health_survey",
    "sql": "SELECT q.questionid, q.questiontext, GROUP_CONCAT(DISTINCT a.AnswerText) as sample_answers FROM Question q JOIN Answer a ON q.questionid = a.QuestionID GROUP BY q.questionid, q.questiontext"
  },
  {
    "db": "mental_health_survey",
    "sql": "WITH ages AS (SELECT UserID, CAST(AnswerText AS INTEGER) AS age FROM Answer WHERE QuestionID = 1 AND CAST(AnswerText AS INTEGER) BETWEEN 18 AND 65), genders AS (SELECT UserID, AnswerText AS gender FROM Answer WHERE QuestionID = 2 AND AnswerText IN ('Male','Female')), mh_yes AS (SELECT DISTINCT UserID FROM Answer WHERE AnswerText = 'Yes'), combined AS (SELECT a.UserID, g.gender, CASE WHEN a.age BETWEEN 18 AND 34 THEN '18-34' WHEN a.age BETWEEN 35 AND 49 THEN '35-49' WHEN a.age BETWEEN 50 AND 65 THEN '50-65' END AS age_group FROM ages a JOIN genders g ON a.UserID = g.UserID) SELECT c.gender, c.age_group, COUNT(DISTINCT c.UserID) AS total_respondents, SUM(CASE WHEN m.UserID IS NOT NULL THEN 1 ELSE 0 END) AS yes_count, CAST(SUM(CASE WHEN m.UserID IS NOT NULL THEN 1 ELSE 0 END) AS REAL) / COUNT(DISTINCT c.UserID) AS burden_rate FROM combined c LEFT JOIN mh_yes m ON c.UserID = m.UserID WHERE c.age_group IS NOT NULL GROUP BY c.gender, c.age_group ORDER BY c.gender, c.age_group"
  },
  {
    "db": "synthea",
    "sql": "WITH patient_ages AS (SELECT patient, gender, CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', birthdate) AS INTEGER) AS age FROM patients WHERE deathdate IS NULL AND gender IN ('M','F')), patient_age_groups AS (SELECT patient, gender, CASE WHEN age BETWEEN 18 AND 34 THEN '18-34' WHEN age BETWEEN 35 AND 49 THEN '35-49' WHEN age BETWEEN 50 AND 65 THEN '50-65' END AS age_group FROM patient_ages WHERE age BETWEEN 18 AND 65), patient_claims AS (SELECT PATIENT, SUM(TOTAL) AS total_claims FROM claims GROUP BY PATIENT) SELECT pag.gender, pag.age_group, pag.patient, COALESCE(pc.total_claims, 0) AS total_claims FROM patient_age_groups pag LEFT JOIN patient_claims pc ON pag.patient = pc.PATIENT WHERE pag.age_group IS NOT NULL ORDER BY pag.gender, pag.age_group"
  },
  {
    "db": "synthea",
    "sql": "WITH patient_ages AS (SELECT patient, gender, CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', birthdate) AS INTEGER) AS age FROM patients WHERE deathdate IS NULL AND gender IN ('M','F')), patient_age_groups AS (SELECT patient, gender, CASE WHEN age BETWEEN 18 AND 34 THEN '18-34' WHEN age BETWEEN 35 AND 49 THEN '35-49' WHEN age BETWEEN 50 AND 65 THEN '50-65' END AS age_group FROM patient_ages WHERE age BETWEEN 18 AND 65), patient_claims AS (SELECT PATIENT, SUM(TOTAL) AS total_claims FROM claims GROUP BY PATIENT) SELECT pag.gender, pag.age_group, COUNT(pag.patient) AS n, AVG(COALESCE(pc.total_claims, 0)) AS mean_claims, SUM(COALESCE(pc.total_claims, 0) * COALESCE(pc.total_claims, 0)) AS sum_sq, SUM(COALESCE(pc.total_claims, 0)) AS sum_claims FROM patient_age_groups pag LEFT JOIN patient_claims pc ON pag.patient = pc.PATIENT WHERE pag.age_group IS NOT NULL GROUP BY pag.gender, pag.age_group ORDER BY pag.gender, pag.age_group"
  }
]

I need to compute the Pearson correlation between each school's spending-to-labor-market ratio and its student adverse outcome rate.

Let me break this down:
1. Get exp_award_value for each school from college_completion
2. Get average max salary of bachelor's-level positions from human_resources
3. Get adverse outcome rate per school from student_loan
4. Compute the ratio and correlation

First, let me get the spending-to-labor-market ratio (exp_award_value / avg max salary of bachelor's positions):

For the spending ratio, I need exp_award_value from institution_details for the mapped schools.

For adverse outcome rate per school: students with adverse outcomes (unemployed, filed for bankruptcy, or payment due) divided by total students enrolled at each school.

Let me write the queries:

[
  {
    "db": "college_completion",
    "sql": "SELECT CASE chronname WHEN 'Orange Coast College' THEN 'occ' WHEN 'Santa Monica College' THEN 'smc' WHEN 'University of California-Berkeley' THEN 'ucb' WHEN 'University of California-Los Angeles' THEN 'ucla' WHEN 'University of California-San Diego' THEN 'ucsd' WHEN 'University of California-Irvine' THEN 'uci' END AS school, exp_award_value FROM institution_details WHERE chronname IN ('Orange Coast College','Santa Monica College','University of California-Berkeley','University of California-Los Angeles','University of California-San Diego','University of California-Irvine')"
  },
  {
    "db": "human_resources",
    "sql": "SELECT AVG(CAST(REPLACE(REPLACE(maxsalary,'US$',''),',','') AS REAL)) AS avg_max_salary FROM position p JOIN employee e ON p.positionID = e.positionID WHERE p.educationrequired = '4 year degree'"
  },
  {
    "db": "student_loan",
    "sql": "SELECT e.school, COUNT(DISTINCT e.name) AS total_students, COUNT(DISTINCT CASE WHEN u.name IS NOT NULL OR b.name IS NOT NULL OR npd.bool = 'pos' THEN e.name END) AS adverse_students, CAST(COUNT(DISTINCT CASE WHEN u.name IS NOT NULL OR b.name IS NOT NULL OR npd.bool = 'pos' THEN e.name END) AS REAL) / COUNT(DISTINCT e.name) AS adverse_rate FROM enrolled e LEFT JOIN unemployed u ON e.name = u.name LEFT JOIN filed_for_bankrupcy b ON e.name = b.name LEFT JOIN no_payment_due npd ON e.name = npd.name WHERE e.school IN ('occ','smc','ucb','ucla','ucsd','uci') GROUP BY e.school"
  },
  {
    "db": "college_completion",
    "sql": "WITH school_map AS (SELECT CASE chronname WHEN 'Orange Coast College' THEN 'occ' WHEN 'Santa Monica College' THEN 'smc' WHEN 'University of California-Berkeley' THEN 'ucb' WHEN 'University of California-Los Angeles' THEN 'ucla' WHEN 'University of California-San Diego' THEN 'ucsd' WHEN 'University of California-Irvine' THEN 'uci' END AS school, exp_award_value FROM institution_details WHERE chronname IN ('Orange Coast College','Santa Monica College','University of California-Berkeley','University of California-Los Angeles','University of California-San Diego','University of California-Irvine')) SELECT school, exp_award_value FROM school_map WHERE school IS NOT NULL"
  }
]

After reviewing, I'll consolidate into the final correlation query using student_loan as the main db and hardcode the ratios, but since we need cross-db, let me provide the queries that together enable the computation:

[{"db": "college_completion", "sql": "SELECT CASE chronname WHEN 'Orange Coast College' THEN 'occ' WHEN 'Santa Monica College' THEN 'smc' WHEN 'University of California-Berkeley' THEN 'ucb' WHEN 'University of California-Los Angeles' THEN 'ucla' WHEN 'University of California-San Diego' THEN 'ucsd' WHEN 'University of California-Irvine' THEN 'uci' END AS school, exp_award_value FROM institution_details WHERE chronname IN ('Orange Coast College','Santa Monica College','University of California-Berkeley','University of California-Los Angeles','University of California-San Diego','University of California-Irvine') AND chronname IS NOT NULL"}, {"db": "human_resources", "sql": "SELECT AVG(CAST(REPLACE(REPLACE(maxsalary,'US$',''),',','') AS REAL)) AS avg_max_salary FROM position WHERE educationrequired = '4 year degree'"}, {"db": "student_loan", "sql": "SELECT e.school, CAST(COUNT(DISTINCT CASE WHEN u.name IS NOT NULL OR b.name IS NOT NULL OR npd.bool = 'pos' THEN e.name END) AS REAL) / NULLIF(COUNT(DISTINCT e.name), 0) AS adverse_rate FROM enrolled e LEFT JOIN unemployed u ON e.name = u.name LEFT JOIN filed_for_bankrupcy b ON e.name = b.name LEFT JOIN no_payment_due npd ON e.name = npd.name WHERE e.school IN ('occ','smc','ucb','ucla','ucsd','uci') GROUP BY e.school"}]

I need to calculate two proportions and then compute the z-statistic for a two-proportion z-test.

Let me gather the data needed:

1. p1: proportion of active loans (status C or D) that are delinquent (status D)
2. p2: proportion of hospitalized patients (Admission = '+') with thrombosis (Thrombosis >= 1)

Then compute z = (p1 - p2) / sqrt(p_pool * (1 - p_pool) * (1/n1 + 1/n2))

[
  {
    "db": "financial",
    "sql": "SELECT SUM(CASE WHEN status = 'D' THEN 1 ELSE 0 END) * 1.0 / COUNT(*) AS p1, SUM(CASE WHEN status = 'D' THEN 1 ELSE 0 END) AS x1, COUNT(*) AS n1 FROM loan WHERE status IN ('C', 'D')"
  },
  {
    "db": "thrombosis_prediction",
    "sql": "SELECT SUM(CASE WHEN e.Thrombosis >= 1 THEN 1 ELSE 0 END) * 1.0 / COUNT(*) AS p2, SUM(CASE WHEN e.Thrombosis >= 1 THEN 1 ELSE 0 END) AS x2, COUNT(*) AS n2 FROM Patient p JOIN Examination e ON p.ID = e.ID WHERE p.Admission = '+'"
  },
  {
    "db": "financial",
    "sql": "WITH loan_stats AS (SELECT SUM(CASE WHEN status = 'D' THEN 1 ELSE 0 END) * 1.0 AS x1, COUNT(*) * 1.0 AS n1 FROM loan WHERE status IN ('C', 'D')), thrombosis_stats AS (SELECT SUM(CASE WHEN e.Thrombosis >= 1 THEN 1 ELSE 0 END) * 1.0 AS x2, COUNT(*) * 1.0 AS n2 FROM Patient p JOIN Examination e ON p.ID = e.ID WHERE p.Admission = '+') SELECT x1/n1 AS p1, x2/n2 AS p2, (x1/n1 - x2/n2) / SQRT(((x1+x2)/(n1+n2)) * (1 - (x1+x2)/(n1+n2)) * (1.0/n1 + 1.0/n2)) AS z FROM loan_stats, thrombosis_stats"
  }
]
